const navbar_menu_firsat_icon_css = () => {
  const style = `
      <style id="anatomi_firsat_icon_css">    
      .bottomHead ul li{
      width: 20% !important;
      }
      .anatomi_firsat_link span{
      color: orange !important;
      }
      .anatomi_homepage_updates, .anatomi_favoriler_updates, .anatomi_sepetim_updates, .anatomi_firsat_updates ,.anatomi_hesabim_updates{
     width: 28px !important;
     height: 24px;
      }

      
      </style>
    `;
  const head = document.querySelector("head");
  const css = document.querySelector("#anatomi_firsat_icon_css");
  if (!css) {
    head.insertAdjacentHTML("beforeend", style);
  }
};

